{
  "summary": "Gather current contract terms, renewal/price-increase policy, SLA performance history, and any credits owed, then draft a response to Acme Cloud Services addressing the proposed 12% increase and renewal terms.",
  "reply_type": "vendor_email",
  "steps": [
    {
      "id": 1,
      "agent": "retriever",
      "task": "List and read the current Acme Cloud Services contract (end date, pricing, renewal clauses, price-increase caps), read the vendor pricing/renewal policy document, read SLA terms and performance/incident records for the contract period, and run the SLA credit calculator to determine any credits owed to us; if any amounts are listed in USD or another foreign currency, use the currency converter to express them in our reporting currency.",
      "why": "The executor needs the exact contract terms, applicable policy limits on price increases, SLA performance data, and any credits owed before a renewal response can be drafted."
    },
    {
      "id": 2,
      "agent": "executor",
      "task": "Draft the reply to Acme Cloud Services acknowledging the contract end date, referencing the current terms and policy on allowable price increases, presenting any SLA credits owed as an offset, and proposing a renewal position (accept, counter-offer, or negotiate the 12% increase) for human review and approval.",
      "why": "The executor synthesizes all gathered facts into the final vendor-facing response for approval."
    }
  ],
  "escalate": null
}
